java="package com.otgflasher.pro;\nimport "+A+".app.PendingIntent; import "+A+".content.*; import "+A+".hardware.usb.*; import "+A+".net.Uri; import "+A+".os.Bundle; import "+A+".widget.*; import androidx.appcompat.app.AppCompatActivity; import java.io.*; import java.util.HashMap;\npublic class MainActivity extends AppCompatActivity { TextView tvLog, tvUsb, tvPath; EditText etCmd; String selectedPath=\"\"; String adbPath=\"\"; UsbManager usbManager; static final String ACTION_USB=\"com.otgflasher.pro.USB\"; @Override protected void onCreate(Bundle b){ super.onCreate(b); setContentView(R.layout.activity_main); tvLog=findViewById(R.id.tvLog); tvUsb=findViewById(R.id.tvUsb); tvPath=findViewById(R.id.tvPath); etCmd=findViewById(R.id.etCmd); usbManager=(UsbManager)getSystemService(Context.USB_SERVICE); adbPath=getApplicationInfo().nativeLibraryDir+\"/libadb.so\"; checkUsb(); findViewById(R.id.btnPick).setOnClickListener(v->pickFile()); findViewById(R.id.btnAdb).setOnClickListener(v->exec(\"adb devices\")); findViewById(R.id.btnFastboot).setOnClickListener(v->exec(\"fastboot devices\")); findViewById(R.id.btnBoot).setOnClickListener(v->flash(\"boot\")); findViewById(R.id.btnRecovery).setOnClickListener(v->flash(\"recovery\")); findViewById(R.id.btnSystem).setOnClickListener(v->flash(\"system\")); findViewById(R.id.btnVendor).setOnClickListener(v->flash(\"vendor\")); findViewById(R.id.btnUserdata).setOnClickListener(v->flash(\"userdata\")); findViewById(R.id.btnVbmeta).setOnClickListener(v->exec(\"fastboot --disable-verity --disable-verification flash vbmeta \"+(selectedPath.isEmpty()?\"vbmeta.img\":selectedPath))); findViewById(R.id.btnUnlock).setOnClickListener(v->exec(\"fastboot flashing unlock\")); findViewById(R.id.btnWipe).setOnClickListener(v->exec(\"fastboot -w\")); findViewById(R.id.btnReboot).setOnClickListener(v->exec(\"fastboot reboot\")); findViewById(R.id.btnRun).setOnClickListener(v->{ String c=etCmd.getText().toString().trim(); if(!c.isEmpty()) exec(c); }); registerReceiver(usbReceiver,new IntentFilter(ACTION_USB)); } void checkUsb(){ HashMap<String,UsbDevice> list=usbManager.getDeviceList(); if(list.isEmpty()) tvUsb.setText(\"USB: No OTG\"); else for(UsbDevice d:list.values()){ tvUsb.setText(\"USB Found\"); requestPerm(d); } } void requestPerm(UsbDevice dev){ PendingIntent pi=PendingIntent.getBroadcast(this,0,new Intent(ACTION_USB),PendingIntent.FLAG_MUTABLE); usbManager.requestPermission(dev,pi); } BroadcastReceiver usbReceiver=new BroadcastReceiver(){ public void onReceive(Context c,Intent i){ if(ACTION_USB.equals(i.getAction())){ boolean ok=i.getBooleanExtra(UsbManager.EXTRA_PERMISSION_GRANTED,false); tvUsb.setText(ok?\"USB OK\":\"USB Denied\"); } } }; void pickFile(){ Intent intent=new Intent(Intent.ACTION_GET_CONTENT); intent.setType(\"*/*\"); startActivityForResult(intent,99); } @Override protected void onActivityResult(int req,int res,Intent data){ super.onActivityResult(req,res,data); if(req==99 && res==RESULT_OK && data!=null){ Uri uri=data.getData(); try{ InputStream is=getContentResolver().openInputStream(uri); File out=new File(getCacheDir(),\"flash.img\"); FileOutputStream fos=new FileOutputStream(out); byte[] buf=new byte[8192]; int len; while((len=is.read(buf))>0) fos.write(buf,0,len); fos.close(); is.close(); selectedPath=out.getAbsolutePath(); tvPath.setText(selectedPath); log(\"> Loaded \"+out.length()/1024+\"KB\"); } catch(Exception e){} } } void flash(String p){ if(selectedPath.isEmpty()){ log(\"! Pick IMG first\"); return; } exec(\"fastboot flash \"+p+\" \"+selectedPath); } void exec(String cmd){ log(\"$ \"+cmd); new Thread(()->{ try{ File f=new File(adbPath); Process pr; String full=cmd.startsWith(\"adb\")?adbPath+\" \"+cmd.substring(3):cmd.startsWith(\"fastboot\")?adbPath+\" \"+cmd:cmd; if(f.exists() && f.length()>1000) pr=Runtime.getRuntime().exec(full); else { try{ pr=Runtime.getRuntime().exec(new String[]{\"su\",\"-c\",cmd}); } catch(Exception e){ pr=Runtime.getRuntime().exec(new String[]{\"sh\",\"-c\",cmd}); } } BufferedReader br=new BufferedReader(new InputStreamReader(pr.getInputStream())); BufferedReader be=new BufferedReader(new InputStreamReader(pr.getErrorStream())); String l; while((l=br.readLine())!=null){ String ll=l; runOnUiThread(()->log(ll)); } while((l=be.readLine())!=null){ String ll=l; runOnUiThread(()->log(ll)); } pr.waitFor(); runOnUiThread(()->log(\"> done\")); } catch(Exception e){ runOnUiThread(()->log(\"ERR \"+e.getMessage())); } }).start(); } void log(String s){ runOnUiThread(()->{ tvLog.append(\"\n\"+s); }); } }"
open("app/src/main/java/com/otgflasher/pro/MainActivity.java","w").write(java)
